const fs = require("fs");
const path = require("path");
const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const dir = fs.mkdtempSync("/tmp/proj-");
fs.mkdirSync(path.join(dir, "src"));
fs.writeFileSync(path.join(dir, "src/index.ts"), "export default { async fetch() { return new Response(\"ok\"); } };\n");
fs.writeFileSync(path.join(dir, "wrangler.toml"), "name = \"test-worker\"\nmain = \"src/index.ts\"\ncompatibility_date = \"2026-08-04\"\n");
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "types"], { cwd: dir, encoding: "utf8", timeout: 80000, env: { ...process.env, HOME: "/tmp", CI: "true", WRANGLER_SEND_METRICS: "false", WRANGLER_LOG_PATH: "/tmp/wrangler-logs" } });
if (r.status !== 0) broken("wrangler types exited " + r.status + ": " + (r.stderr || "").slice(-800) + (r.stdout || "").slice(-800));
const out = path.join(dir, "worker-configuration.d.ts");
if (!fs.existsSync(out)) broken("worker-configuration.d.ts was not written");
const file = fs.readFileSync(out, "utf8");
if (!/interface ExecutionContext\b/.test(file)) broken("generated file has no runtime types");
const m = file.match(/^declare (?:const|let|var) (Buffer|process)\b.*$/m);
if (m) symptom("wrangler types generated a Node.js global for a date-enabled Node.js compat config: " + m[1]);
console.log("OK: no Buffer or process global declarations in generated runtime types");

